import{_ as i,o as a,c as e,ak as d}from"./chunks/framework.DvrM7GBU.js";const _=JSON.parse('{"title":"维护流程说明","description":"","frontmatter":{},"headers":[],"relativePath":"维护与报告/维护流程说明.md","filePath":"维护与报告/维护流程说明.md","lastUpdated":1776864657000}'),r={name:"维护与报告/维护流程说明.md"};function o(c,l,h,t,n,s){return a(),e("div",null,[...l[0]||(l[0]=[d('<h1 id="维护流程说明" tabindex="-1">维护流程说明 <a class="header-anchor" href="#维护流程说明" aria-label="Permalink to “维护流程说明”">​</a></h1><p>一句话摘要：这是一份面向资料库维护者的执行说明，帮助你按统一顺序完成查缺、补证、修文、回链和状态更新，避免越修越乱。</p><ul><li>适合对象：维护者、整理者、后续协作者</li><li>当前状态：已整理</li><li>可信度：<code>[已确认]</code></li><li>关联文档：<code>docs/维护与报告/资料规范与状态总览.md</code>、<code>docs/OCR 完整化推进清单.md</code>、<code>docs/错误点与优化点汇总.md</code></li></ul><h2 id="推荐维护流程" tabindex="-1">推荐维护流程 <a class="header-anchor" href="#推荐维护流程" aria-label="Permalink to “推荐维护流程”">​</a></h2><h3 id="第一步-先判断这次维护属于哪一类" tabindex="-1">第一步：先判断这次维护属于哪一类 <a class="header-anchor" href="#第一步-先判断这次维护属于哪一类" aria-label="Permalink to “第一步：先判断这次维护属于哪一类”">​</a></h3><ul><li>补导航</li><li>补专题正文</li><li>补 OCR 证据</li><li>修错误链接</li><li>修术语和分类</li><li>更新状态与路线图</li></ul><h3 id="第二步-先看治理文档" tabindex="-1">第二步：先看治理文档 <a class="header-anchor" href="#第二步-先看治理文档" aria-label="Permalink to “第二步：先看治理文档”">​</a></h3><p>优先阅读：</p><ol><li><code>docs/维护与报告/资料规范与状态总览.md</code></li><li><code>docs/错误点与优化点汇总.md</code></li><li><code>docs/待验证问题清单.md</code></li></ol><h3 id="第三步-定位改动层级" tabindex="-1">第三步：定位改动层级 <a class="header-anchor" href="#第三步-定位改动层级" aria-label="Permalink to “第三步：定位改动层级”">​</a></h3><p>优先级建议：</p><ol><li>先修总导航和栏目导航</li><li>再修高价值专题页</li><li>再补 OCR 证据链</li><li>最后再做细枝末节的格式统一</li></ol><h3 id="第四步-改完后必须补回链" tabindex="-1">第四步：改完后必须补回链 <a class="header-anchor" href="#第四步-改完后必须补回链" aria-label="Permalink to “第四步：改完后必须补回链”">​</a></h3><p>每次新增或扩写页面，至少检查：</p><ul><li>是否能从总导航进入</li><li>是否能从所属栏目页进入</li><li>是否写了关联阅读</li><li>是否有必要回链到 OCR / 维护页</li></ul><h3 id="第五步-更新状态" tabindex="-1">第五步：更新状态 <a class="header-anchor" href="#第五步-更新状态" aria-label="Permalink to “第五步：更新状态”">​</a></h3><p>改完后应尽量同步更新：</p><ul><li>当前状态</li><li>可信度</li><li>待验证项</li><li>仍可继续补强的部分</li></ul><h2 id="维护时最容易出的问题" tabindex="-1">维护时最容易出的问题 <a class="header-anchor" href="#维护时最容易出的问题" aria-label="Permalink to “维护时最容易出的问题”">​</a></h2><ul><li>只补正文，不补入口</li><li>只补入口，不补回链</li><li>只写结论，不写可信度</li><li>只做分类，不做使用说明</li><li>不区分“已确认”和“待验证”</li></ul><h2 id="推荐的单次维护目标" tabindex="-1">推荐的单次维护目标 <a class="header-anchor" href="#推荐的单次维护目标" aria-label="Permalink to “推荐的单次维护目标”">​</a></h2><p>一次维护最好只聚焦一种目标，例如：</p><ul><li>把一个栏目补完整</li><li>把 3~5 篇高价值专题补统一头部</li><li>把一组 OCR 证据整理成可回链结构</li><li>把一批错误链接和命名问题统一修掉</li></ul><h2 id="收尾检查清单" tabindex="-1">收尾检查清单 <a class="header-anchor" href="#收尾检查清单" aria-label="Permalink to “收尾检查清单”">​</a></h2><ul><li>[ ] 路径是否正确</li><li>[ ] 标题是否明确</li><li>[ ] 有无一句话摘要</li><li>[ ] 有无适合对象 / 当前状态 / 可信度</li><li>[ ] 有无关联阅读</li><li>[ ] 是否接入栏目或总导航</li></ul><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to “关联阅读”">​</a></h2><ul><li><code>docs/维护与报告/维护与报告导航.md</code></li><li><code>docs/维护与报告/资料规范与状态总览.md</code></li><li><code>docs/总索引与导航/创游世界知识库总导航.md</code></li></ul>',27)])])}const p=i(r,[["render",o]]);export{_ as __pageData,p as default};
